llm_engineering/application/preprocessing/operations/chunking.py<pre><code>from langchain.text_splitter import RecursiveCharacterTextSplitter

class TaxBillChunker:
    def __init__(
        self,
        chunk_size: int = 1000,
        chunk_overlap: int = 200
    ):
        self.splitter = RecursiveCharacterTextSplitter(
            chunk_size=chunk_size,
            chunk_overlap=chunk_overlap,
            separators=["\n\n", "\n", ". ", " "]
        )

    def chunk(self, document: Document) -&gt; List[Chunk]:
        texts = self.splitter.split_text(document.content)
        return [
            Chunk(
                content=text,
                document_id=document.id,
                metadata=document.metadata
            )
            for text in texts
        ]
</code></pre>

llm_engineering/application/preprocessing/embedding_data_handlers.py<pre><code>class EmbeddingHandler:
    def __init__(self):
        self.model = SentenceTransformer(settings.EMBEDDING_MODEL_ID)

    def embed_chunks(
        self,
        chunks: List[Chunk],
        batch_size: int = 32
    ) -&gt; List[EmbeddedChunk]:
        embeddings = self.model.encode(
            [c.content for c in chunks],
            batch_size=batch_size,
            show_progress_bar=True
        )

        return [
            EmbeddedChunk(
                chunk=chunk,
                embedding=embedding.tolist()
            )
            for chunk, embedding in zip(chunks, embeddings)
        ]
